'use client'

import { useEffect, useMemo, useState } from 'react'

type Stage = 'Atendimento' | 'Orçamento' | 'Aprovado' | 'Arte' | 'Produção' | 'Instalação' | 'Concluído' | 'Cancelado'
type BoardStage = Exclude<Stage,'Cancelado'>
type Service = {
  id: string
  dbId?: string
  client: string
  title: string
  value: number
  stage: Stage
  due: string
  progress: number
  color: string
  estimatedCost?: number
  actualCost?: number
  estimatedMargin?: number
  minimumMargin?: number
  suggestedPrice?: number
  quoteValidUntil?: string
  paymentTerms?: string
  quoteNotes?: string
  discount?: number
  productionHours?: number
  installationHours?: number
  machineHours?: number
  travelKm?: number
  installationScheduledAt?: string
  installationTeam?: string
  installationAddress?: string
  installationNotes?: string
  responsible?: string
  priority?: 'normal'|'alta'|'urgente'
}

const stages: BoardStage[] = ['Atendimento', 'Orçamento', 'Aprovado', 'Arte', 'Produção', 'Instalação', 'Concluído']

const initialServices: Service[] = []

const money = (v:number) => v.toLocaleString('pt-BR',{style:'currency',currency:'BRL'})

